// ===== 1. Extract raw LLM output =====
let rawText = null;
try {
  rawText = $json.output[0].content[0].text;
} catch (e) {
  rawText = null;
}

// ===== 2. Parse JSON =====
let parsed = {};
try {
  parsed = rawText ? JSON.parse(rawText) : {};
} catch (e) {
  parsed = {};
}

// ===== 3. Normalize fields with fallback =====
const now = new Date().getFullYear();

const title = parsed.title && parsed.title.trim() !== '' ? parsed.title.trim() : 'biomedical research';
const body = parsed.body && parsed.body.trim() !== '' ? parsed.body.trim() : null;
const yearFrom = parsed.year_from && !isNaN(parsed.year_from) ? parsed.year_from : now - 10;
const yearTo = parsed.year_to && !isNaN(parsed.year_to) ? parsed.year_to : now;
let retmax = parsed.retmax && !isNaN(parsed.retmax) ? Math.min(Math.max(parsed.retmax, 1), 10) : 3;

// ===== 4. Helper function: escape terms for PubMed =====
function escapePubMedTerm(term) {
  // Laita lainausmerkkeihin jos useampi sana
  if (/\s/.test(term)) {
    return `"${term}"`;
  }
  return term;
}

// ===== 5. Process title and body =====
let titleTerm = escapePubMedTerm(title);

let bodyTerms = [];
if (body) {
  // Split body by commas or 'and', trim whitespace
  body.split(/,|\band\b/i).forEach(t => {
    const trimmed = t.trim();
    if (trimmed) bodyTerms.push(escapePubMedTerm(trimmed));
  });
}

// Yhdistä body-termien OR:lla ja lisää PubMed field
let bodyQuery = bodyTerms.length ? `(${bodyTerms.join(' OR ')})[Title/Abstract]` : '';

// ===== 6. Build final PubMed query =====
let searchTerm = `${titleTerm}[Title]`;
if (bodyQuery) searchTerm += ` AND ${bodyQuery}`;
searchTerm += ` AND ${yearFrom}/01/01:${yearTo}/12/31[PDAT]`;

// ===== 7. Return for next node =====
return [{
  json: {
    searchTerm,
    retmax,
    debug: {
      normalized: { title, body, yearFrom, yearTo, retmax },
      original: $json
    }
  }
}];

