const items = $input.all();

function stripTags(str) {
  return str ? str.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() : '';
}

function cleanXML(str, maxLength = 2000) {
  return stripTags(str).substring(0, maxLength);
}

return items.map((item, index) => {
  const xml = item.json.data || item.json;

  const title = xml.match(/<article-title[^>]*>(.*?)<\/article-title>/s);
  const abstract = xml.match(/<abstract[^>]*>(.*?)<\/abstract>/s);
  const year = xml.match(/<pub-date[^>]*>.*?<year>(\d{4})<\/year>/s);
  const authorsBlock = xml.match(/<contrib-group[^>]*>(.*?)<\/contrib-group>/s);
  const results = xml.match(/<sec[^>]*>.*?<title[^>]*>Results<\/title>(.*?)<\/sec>/si);
  const discussion = xml.match(/<sec[^>]*>.*?<title[^>]*>Discussion<\/title>(.*?)<\/sec>/si);
  const conclusion = xml.match(/<sec[^>]*>.*?<title[^>]*>Conclusion[s]?<\/title>(.*?)<\/sec>/si);

  let authors = 'Unknown';
  if (authorsBlock) {
    const names = authorsBlock[1].match(/<surname>(.*?)<\/surname>.*?<given-names>(.*?)<\/given-names>/gs);
    if (names) {
      authors = names.map(n => {
        const s = n.match(/<surname>(.*?)<\/surname>/);
        const g = n.match(/<given-names>(.*?)<\/given-names>/);
        return `${g ? g[1] : ''} ${s ? s[1] : ''}`.trim();
      }).join(', ');
    }
  }

  return {
    json: {
      pmcid: item.json.pmcid || null,
      articleIndex: index + 1,
      textForSummary: `
TITLE: ${title ? stripTags(title[1]) : 'No title'}
AUTHORS: ${authors}
YEAR: ${year ? year[1] : 'Unknown'}
ABSTRACT: ${abstract ? cleanXML(abstract[1], 1500) : 'No abstract'}
RESULTS: ${results ? cleanXML(results[1], 2000) : 'Not found in XML'}
DISCUSSION: ${discussion ? cleanXML(discussion[1], 2000) : 'Not found in XML'}
CONCLUSION: ${conclusion ? cleanXML(conclusion[1], 1000) : 'Not found in XML'}
      `.trim()
    }
  };
});

return $input.all().map(item => {
  // Puretaan JSON-string output-kentästä
  let data = {};
  try {
    data = JSON.parse(item.json.output);
  } catch (e) {
    data = {};
  }

  // Abbreviations käsittely
  let abbreviations = '';
  if (typeof data.abbreviations === 'object') {
    abbreviations = Object.entries(data.abbreviations)
      .map(([k, v]) => `${k}: ${v}`)
      .join(', ');
  } else {
    abbreviations = data.abbreviations || '';
  }

  let message = `
📄 ${data.title}

🎯 Objective:
${data.objective}

🧪 Methods:
${data.methods}

🔬 Key Findings:
${data.key_findings}

🌍 Significance:
${data.significance}

🔤 Abbreviations:
${abbreviations}

💡 Speculation:
${data.speculation}

⚠️ Limitations:
${data.limitations}
`.trim();

  if (message.length > 4000) {
    message = message.substring(0, 3900) + '\n\n... (truncated)';
  }

  return { json: { text: message } };
});
